// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2007, "8-9", [{"author":"И. Рубанов","question":"Какое из этих слов не является звукоподражанием?","choices":["<em>жужжать</em>","<em>шуршать</em>","<em>шипеть</em>","<em>мычать</em>","<em>молчать</em>."],"key":"Д","review":["Слова, похожие на звуки","Подумай, имитирует ли глагол голос, трение или другой слышимый звук.","«Жужжать», «шуршать», «шипеть» и «мычать» передают звучание. «Молчать» означает отсутствующий голос и звука не изображает."]},{"author":"О. Шеманаева","question":"<em>Саша — мой ... друг</em>.","choices":["<em>завзятый</em>","<em>закоренелый</em>","<em>закадычный</em>","<em>застарелый</em>","<em>заядлый</em>."],"key":"В","review":["Прилагательное о друге","Нужно привычное сочетание о близком друге. Другие варианты чаще описывают увлечения или застарелые привычки.","«Закадычный друг» — давний и очень близкий друг. Это устойчивое сочетание."]},{"author":"И. Иткин","question":"<em>Вот тебе, бабка, Юрьев день,\nвот тебе, шапка, твой бекрень,\nвот тебе, друг степей и джунглей,\nтвой бюллетень, пельмень, женьшень...</em>\nКакого из слов, встретившихся в этих шутливых строчках М. Щербакова, на самом деле не существует?","choices":["<em>бекрень</em>","<em>бюллетень</em>","<em>пельмень</em>","<em>женьшень</em>","все эти слова существуют."],"key":"А","review":["Слово для рифмы","Проверь не только значение, но и употребление слова отдельно. Вспомни устойчивое сочетание о наклонённой шапке.","Говорят «шапка набекрень». Отдельного слова «бекрень» в обычном употреблении нет, хотя в стихах оно выделено для рифмы."]},{"author":"С. Бурлак","question":"Какую букву нельзя вставить в слово <em>пр...ходящий</em>?","choices":["<em>а</em>","<em>е</em>","<em>и</em>","<em>о</em>","вставить можно любую из этих букв."],"key":"А","review":["Буква в начале причастия","Попробуй прочитать каждый вариант и объяснить его, например «который проходит» или «временный».","Существуют «приходящий», «проходящий» и «преходящий». В форме «праходящий» нет подходящей приставки или корня."]},{"author":"Б. Иомдин","question":"Какое числительное скорее всего может встретиться в следующем предложении: <em>Ей было слегка за…</em>?","choices":["1","10","30","57","100."],"key":"В","review":["Возраст в разговоре","Выражение «слегка за» обычно используют, когда возраст ненамного превышает круглую дату взрослого человека.","Привычнее всего «слегка за тридцать», то есть немного больше тридцати лет."]},{"author":"П. Аркадьев","question":"В каких из приведённых предложений слова <em>то есть</em> можно заменить на сокращение <em>т. е.</em>?\n1) Раз он уже выехал, то есть надежда, что он опоздает не больше чем на полчаса.\n2) У тебя есть температура? — То есть, то нет.\n3) Полифония, то есть многоголосие, появляется в европейской музыке только в Средние века.\n4) Мне всё время хочется то есть, то пить.","choices":["в первом","во втором","в третьем","в четвёртом","во всех."],"key":"В","review":["Когда «то есть» поясняет","Подставь «иначе говоря». Проверь, где сочетание вводит пояснение, а где слова выполняют отдельные роли.","Только в третьем предложении «то есть» поясняет, что полифония — многоголосие. Там и подходит сокращение «т. е.»."]},{"author":"И. Рубанов","question":"Диктор сказал: «<em>На дорогах Бельгии образовались пробки общей длительностью 350 км</em>». А как надо было сказать?","choices":["так и надо было","<em>общей продолжительностью 350 км</em>","<em>общей протяжённостью 350 км</em>","<em>общим расстоянием 350 км</em>","<em>общей численностью 350 км</em>."],"key":"В","review":["Что измеряется километрами","Проверь, сообщают ли километры длительность пробок или длину участков дорог, которые они заняли.","В километрах измеряют протяжённость. Нужно «пробки общей протяжённостью 350 км»."]},{"author":"С. Переверзева","question":"Какое из этих пяти слов не имеет той общей смысловой части, которая есть у остальных четырёх?","choices":["<em>радиоволна</em>","<em>радиотехника</em>","<em>радиосвязь</em>","<em>радиоактивность</em>","<em>радиопередача</em>."],"key":"Г","review":["Смыслы начала «радио»","Различи радиовещание и передачу сигнала с одной стороны и излучение веществ с другой.","Радиотехника, радиоволна, радиосвязь и радиопередача связаны со связью. «Радиоактивность» означает способность вещества испускать излучение при распаде."]},{"author":"Н. Валеева","question":"Саша Привалов, герой повести братьев Стругацких «Понедельник начинается в субботу», однажды сочинил такие агитационные стихи:\n<em>Раскопай своих подвалов\nИ шкафов перетряси,\nРазных книжек и журналов\nПо возможности неси.</em>\nДопустил ли он при этом грамматическую ошибку, и если да, то какую?","choices":["Да: несколько раз употребил родительный падеж вместо винительного.","Да: несколько раз употребил родительный падеж вместо именительного.","Да: несколько раз употребил винительный падеж вместо именительного.","Да: несколько раз употребил винительный падеж вместо родительного.","Грамматических ошибок в этих стихах нет."],"key":"А","review":["Падежи в стихах","Проверь, какой падеж требуют «раскопай» и «перетряси». Стихотворный ритм не меняет управления.","Нужно «раскопай подвалы» и «перетряси шкафы». В этих местах родительный «подвалов», «шкафов» употреблён вместо винительного."]},{"author":"О. Шеманаева","question":"В какое слово на место пропуска можно вставить <em>тц</em>?","choices":["<em>…унами</em>","<em>репети…ия</em>","<em>пла…</em>","<em>о…епить</em>","<em>о…енить</em>."],"key":"Г","review":["Две согласные в пропуске","Восстанови слова одно за другим. Для одного из них «т» и «ц» относятся к разным частям слова.","Пишут «отцепить»: «т» входит в приставку «от-», «ц» начинает основу «цеп-». В других пропусках такого сочетания нет."]},{"author":"И. Иткин","question":"Какое из этих слов не родственно слову <em>закрыть</em>?","choices":["<em>закройщик</em>","<em>открытие</em>","<em>крышечка</em>","<em>кровля</em>","слову <em>закрыть</em> родственны все эти слова."],"key":"А","review":["Слова с похожим корнем","Сравни значения «накрывать» и «резать по выкройке». Одно из данных слов относится к шитью.","«Закройщик» происходит от «кроить». Остальные слова имеют историческую связь с «крыть», как и «закрыть»."]},{"author":"Н. Валеева","question":"О скрытном, хитром, расчётливом человеке говорят, что он:","choices":["<em>сам себе голова</em>","<em>сам по себе</em>","<em>себе на уме</em>","<em>ума палата</em>","<em>задним умом крепок</em>."],"key":"В","review":["Как говорят о скрытности","Вспомни выражение о человеке, который склонен держать собственные замыслы при себе.","О хитром и скрытном человеке говорят «себе на уме». Другие обороты описывают самостоятельность, ум или позднюю догадку."]},{"author":"И. Иткин","question":"1) <em>Благодаря своим друзьям я почувствовал, что не одинок.</em>\n2) <em>Благодаря своих друзей я почувствовал, что не одинок.</em>\n3) <em>Благодаря своих друзей, я почувствовал, что не одинок.</em>\nКакие из этих фраз написаны правильно?","choices":["только 1","только 2","только 3","1 и 2","1 и 3."],"key":"Д","review":["Предлог и деепричастие","В первом предложении проверь падеж после «благодаря». В других попробуй заменить это слово на «выражая благодарность».","В 1 предлог требует дательного «друзьям». В 3 деепричастный оборот «благодаря своих друзей» имеет винительный и отделяется запятой. В 2 запятая пропущена."]},{"author":"Н. Валеева","question":"Даны слова <em>подлежащее, дополнение, определение, обстоятельство</em>. Сколько из них могут быть не только названиями членов предложения?","choices":["ни одного","одно","два","три","все четыре."],"key":"Д","review":["Значения грамматических слов","Подбери к каждому термину выражение за пределами школьного разбора, например «обстоятельства дела».","Есть «подлежащее оплате», «дополнение к отчёту», «определение числа», «обстоятельство дела». У каждого из четырёх слов есть другое употребление."]},{"author":"И. Рубанов","question":"«<em>Нашей пицце нельзя не удивиться!</em>» — написано при входе в одну пиццерию. А как наиболее точно изложить ту же мысль, не употребляя частицы <em>не</em>?","choices":["<em>Нашей пицце можно удивляться!</em>","<em>Нашей пицце хочется удивляться!</em>","<em>Нашей пицце нетрудно удивиться!</em>","<em>Нашей пицце обязательно удивишься!</em>","<em>Нашей пицце устанешь удивляться!</em>"],"key":"Г","review":["Двойное отрицание о пицце","«Нельзя не удивиться» означает, что удивление непременно произойдёт. Ищи фразу с такой же силой утверждения.","«Нашей пицце обязательно удивишься!» передаёт неизбежность. «Можно удивляться» и «хочется удивляться» выражают более слабую мысль."]},{"author":"Е. Муравенко","question":"В каком из предложений союз <em>если …, то</em> имеет не такое значение, как в остальных?","choices":["<em>Если в 2000 году в «Русском медвежонке» приняли участие 64 тысячи школьников, то в 2006 году участников было уже более 1 миллиона 400 тысяч</em>.","<em>Если число участников и дальше будет так же расти, то в этом году в «Русском медвежонке» будет участвовать более полутора миллионов школьников</em>.","<em>Если вы успешно решите задания «Русского медвежонка», то получите призы</em>.","<em>Если в этом году вам не удастся справиться со всеми задачами, то не стоит расстраиваться, а надо просто лучше подготовиться к конкурсу в следующем году</em>.","<em>Если вам хочется обсудить задачи конкурса или другие вопросы по русскому языку, то это можно сделать в Интернете на форуме «Русского медвежонка»</em>."],"key":"А","review":["Два значения «если»","Проверь, где описывается условие или возможность, а где сопоставляются уже известные факты.","В первой фразе сравниваются реальные числа участников в два разных года. Здесь «если… то» служит сопоставлению. В других примерах оно задаёт условие."]},{"author":"Н. Валеева","question":"Восстановите пословицу: <em>И рад бы в рай, да … не пускают</em>.","choices":["<em>ангелы</em>","<em>бесы</em>","<em>враги</em>","<em>грехи</em>","<em>дела</em>."],"key":"Г","review":["Окончание пословицы","Ищи причину, которая мешает попасть в рай в представлении, лежащем в основе пословицы.","Говорят «И рад бы в рай, да грехи не пускают». Грехи объясняют препятствие."]},{"author":"И. Иткин","question":"Какое из этих слов по своим грамматическим характеристикам отличается от остальных?","choices":["<em>золотоискатель</em>","<em>кладоискатель</em>","<em>металлоискатель</em>","<em>правдоискатель</em>","<em>шпагоглотатель</em>."],"key":"В","review":["Грамматические свойства слов","Попробуй образовать винительный множественного: «вижу кого?» или «вижу что?».","«Металлоискатель» в обычном значении — прибор. «Вижу металлоискатели», но «вижу золотоискателей», «кладоискателей», «правдоискателей», «шпагоглотателей»."]},{"author":"Л. Фёдорова","question":"Даны существительные нидерландского языка в формах единственного и множественного числа: taal (язык) — talen (языки), woord (слово) — woorden (слова), pen (перо) — pennen (перья), bank (скамья) — banken (скамьи), hut (каюта) — hutten (каюты), noot (орех) — noten (орехи). Как образовать множественное число следующих существительных: tulp (тюльпан), stuk (кусок), stuur (руль)?","choices":["tulpen, stuken, stuuren","tuulpen, stuuken, stuuren","tulppen, stukken, sturen","tulpen, stukken, sturen","tulpen, stukken, sturren."],"key":"Г","review":["Нидерландское множественное","Сравни, когда удваивается согласная, а когда остаётся одна буква долгого гласного. Выдели общее окончание «-en».","У «tulp» две согласные на конце, получаем «tulpen». Краткая «u» в «stuk» требует «stukken». Долгая «uu» в открытом слоге становится одной буквой: «sturen»."]},{"author":"Н. Валеева","question":"Вот четыре фразы:\n<em>Эта задача более сложнее, чем другие.\nЭта задача наиболее сложнее других.\nЭта задача наиболее самая сложная из всех.\nЭта задача самая сложнейшая из всех.</em>\nСколько среди них грамматически правильных?","choices":["четыре","три","две","одна","ни одной."],"key":"Д","review":["Повтор степени сравнения","Отдельно найди показатели сравнительной и превосходной степени. Убирай лишнее, если оно делает одну работу дважды.","Нужно выбирать «сложнее» или «более сложная», «самая сложная» или «сложнейшая». Во всех четырёх фразах способы смешаны."]},{"author":"Б. Иомдин","question":"Даны слова: <em>всего</em>, <em>ничего</em>, <em>некого</em>, <em>отчего</em>, <em>полого</em>. Сколько из них можно понять как форму родительного падежа?","choices":["одно","два","три","четыре","пять."],"key":"Д","review":["Формы родительного падежа","Подставляй к словам существительные или глаголы, которые требуют родительного. Проверь, есть ли форма «отчий».","Возможны «нет всего», «нет ничего», «некого спросить», «нет отчего дома», «нет полого стебля». Все пять форм могут быть родительными."]},{"author":"Н. Валеева","question":"Даны глаголы <em>выбить</em>, <em>выбыть</em>, <em>выжить</em>, <em>вышить</em>. Сколько из них относятся к I спряжению?","choices":["все четыре","три","два","один","ни одного."],"key":"А","review":["Личные окончания глаголов","Поставь каждый глагол в форму «ты». Приставка «вы-» не меняет спряжения основы.","«Выбьешь», «выбудешь», «выживешь», «вышьешь» имеют «-ешь». Все четыре глагола относятся к I спряжению."]},{"author":"Н. Валеева","question":"Даны пары синонимичных слов и выражений:\n1) <em>(в)потьмах — (в)потёмках</em>;\n2) <em>(по)очерёдно — (по)очереди</em>;\n3) <em>(в)далеке — (в)отдалении</em>;\n4) <em>(до)зарезу — (по)зарез</em>.\nВ каких из них в обоих случаях следует выбрать раздельное написание?","choices":["во всех, кроме 2","в 1 и 3","в 2 и 3","только в 3","двух случаев раздельного написания нет ни в одной из этих пар."],"key":"Д","review":["Слитно или раздельно","Выпиши обе формы каждой пары без скобок. Следи, чтобы в паре обе записи были раздельными.","Получаются «впотьмах — в потёмках», «поочерёдно — по очереди», «вдалеке — в отдалении», «до зарезу — позарез». В каждой паре одно написание слитное."]},{"author":"И. Иткин","question":"У какого из этих глаголов форма страдательного причастия прошедшего времени образуется не так, как у остальных?","choices":["<em>вывалять</em>","<em>выменять</em>","<em>выровнять</em>","<em>высмеять</em>","у всех этих глаголов форма страдательного причастия образуется одинаково."],"key":"В","review":["Суффикс в причастии","Образуй страдательные формы, подставив их к существительному. Сравни гласную перед удвоенным «н».","«Вывалянный», «выменянный», «высмеянный» имеют «-янн-». От «выровнять» получается «выровненный» с «е»."]},{"author":"С. Бурлак","question":"Какой частью речи является слово <em>пропасть</em> в предложении «<em>Блинов напекла пропасть</em>»?","choices":["существительным","наречием","числительным","частицей","междометием."],"key":"А","review":["Значение количества","Проверь, можно ли добавить слово «целая». Блинов много, но «пропасть» сохраняет грамматические свойства названия.","«Целая пропасть блинов» употребляется как количественное выражение. «Пропасть» в нём является существительным."]},{"author":"Е. Муравенко","question":"Сколько разных способов произношения приставки <em>с-</em> представлено в глаголах: <em>сбросил, свил, сжёг, спросил, срезал, сшил</em>?","choices":["2","3","4","5","6."],"key":"В","review":["Произношение приставки «с»","Произнеси каждое слово слитно. Проверь оглушение, озвончение и уподобление шипящим.","Слышатся [з] в «сбросил», [с] в «свил», «спросил», «срезал», долгий [ж] в «сжёг» и долгий [ш] в «сшил». Всего четыре."]},{"author":"К. Кноп","question":"Слово, оканчивающееся на <em>-атая</em>, не может быть:","choices":["деепричастием","причастием","числительным","прилагательным","все варианты (А)–(Г) возможны."],"key":"Д","review":["Конец слова и часть речи","Найди примеры на «-атая», где такое окончание принадлежит разным типам слов. Помни, что это просто последние буквы.","«Латая» — деепричастие, «сжатая» — причастие, «двадцатая» — числительное, «усатая» — прилагательное. Возможны все четыре случая."]},{"author":"И. Иткин","question":"Слово <em>славянофил</em> (так в XIX веке называли сторонников особого, отличного от Западной Европы, пути развития России) обладает одним достаточно редким свойством. Какое из следующих слов обладает тем же свойством?","choices":["<em>патриот</em>","<em>библиофил</em>","<em>кириллица</em>","<em>микроскоп</em>","<em>светофор</em>."],"key":"Д","review":["Корни разного происхождения","Раздели «славянофил» на части. Первая связана со славянами, вторая восходит к греческому слову о любви.","У «светофор» тоже смешанное строение: русское «свет» и греческое «-фор» со значением «несущий». В других вариантах такой пары корней нет."]},{"author":"К. Кноп","question":"Какое слово правильно продолжает следующий ряд: <em>объединение</em>, <em>дуэль</em>, <em>трилогия</em>, <em>квартал</em>, <em>пентаграмма</em>?","choices":["<em>юношество</em>","<em>секта</em>","<em>путешественник</em>","<em>гекзаметр</em>","<em>тетраэдр</em>."],"key":"Г","review":["Числа внутри слов","Ищи значения «один», «два», «три», «четыре», «пять» в словах из списка. Следующий корень обозначает шесть.","«Гекса-» в «гекзаметр» означает «шесть». Это подходящее продолжение ряда после «пента-» со значением «пять»."]},{"author":"А. Бердичевский","question":"У современной поэтессы Новеллы Матвеевой есть стихотворение «Песни Киплинга», ставшее популярной песней. Перед вами — фрагмент этого стихотворения в том виде, в каком он часто печатается и исполняется:\n<em>И взлетела рядом\nС пулей, со снарядом\nПесенка:\nО добрых кобрах,\nО земных нетопырях,\nОб акулах благодарных,\nО казармах светозарных\nИ о радужных холерных лагерях.</em>\nИзвестно, что по сравнению с оригиналом этот вариант содержит одно существенное изменение, отчасти искажающее смысл исходного текста. Какое слово надо заменить, чтобы восстановить правильный текст?","choices":["<em>пулей</em> — на <em>бомбой</em>","<em>добрых</em> — на <em>злобных</em>","<em>земных</em> — на <em>дневных</em>","<em>казармах</em> — на <em>бараках</em>","<em>холерных</em> — на <em>тифозных</em>."],"key":"В","review":["Строка из «Песен Киплинга»","Образы в песне нарочно необычны: кобры добры, акулы благодарны. Найди строку, где замена создаёт такое же неожиданное сочетание.","В оригинале «О дневных нетопырях». Нетопыри обычно ночные, поэтому «дневных» поддерживает игру с необычными свойствами."]}], {"year":2007,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2007.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
